/**
 * 웹앱 다운로드용 정적 자산 — Slack 봇 앱 아이콘 (킹샷 king 이미지, 원본 favicon.ico 600x600 바이트 그대로).
 * 멤버 페이지(index.html)엔 싣지 않음 — apiGetSlackIcon() 으로 버튼 클릭 시에만 전송(lazy).
 * 배포자가 Slack App icon 업로드용으로 받음. 확장자/바이트 원본 동일(.ico, JPEG content).
 */

/** 클릭 시 lazy 호출 — Slack 봇 아이콘 base64(원본) 반환. */
function apiGetSlackIcon() {
  return SLACK_ICON_B64;
}

const SLACK_ICON_B64 =
  '';
